// 假设容器配置结构体定义
typedef struct {
    int id;
    char tag[256];  // 假设标签最大长度为256字节
    int active;
} ContainerConfig;

// 假设有一个全局容器配置数组
static ContainerConfig containers[1000];  // 支持最多1000个容器
static int container_count = 0;

int set_container_tag(int container_id, char* tag_name) {
    // 检查参数有效性
    if (container_id < 0 || tag_name == NULL) {
        return -1;  // 参数错误
    }

    // 查找指定ID的容器
    int container_index = -1;
    for (int i = 0; i < container_count; i++) {
        if (containers[i].id == container_id) {
            container_index = i;
            break;
        }
    }

    // 如果没有找到对应的容器
    if (container_index == -1) {
        return -2;  // 容器不存在
    }

    // 检查标签名称长度，防止缓冲区溢出
    size_t tag_len = strlen(tag_name);
    if (tag_len >= sizeof(containers[container_index].tag)) {
        return -3;  // 标签名称太长
    }

    // 使用strncpy安全复制标签名称
    strncpy(containers[container_index].tag, tag_name, sizeof(containers[container_index].tag) - 1);
    // 确保字符串以null结尾
    containers[container_index].tag[sizeof(containers[container_index].tag) - 1] = '\0';

    return 0;  // 成功设置标签
}
